python3 -c "
import json,hashlib,os
R='/private/tmp/opensip-design-corrections/claude-source37-root-corrections-review.v1/'
m=json.load(open(R+'subject-manifest.json'))
want={f['sha256']:f['path'] for f in m['files']}
names={os.path.basename(f['path']) for f in m['files']}
found={}
roots=['/Users/sb/code/opensip-ai/opensip_arch/docs','/tmp/opensip-design-corrections']
for root in roots:
    for dp,ds,fs in os.walk(root):
        if 'candidate-subject.v' in dp and 'claude-source37-root' not in dp: 
            ds[:]=[]; continue
        for f in fs:
            if f in names:
                p=os.path.join(dp,f)
                try: h=hashlib.sha256(open(p,'rb').read()).hexdigest()
                except Exception as e: continue
                if h in want: found.setdefault(want[h],[]).append(p)
for k in sorted(want.values()): print(k, found.get(k))
"

